function countCompleteSubarrays(nums) {
  const total = new Set(nums).size;
  const count = new Map();
  let left = 0;
  let answer = 0;
  for (let right = 0; right < nums.length; right++) {
    count.set(nums[right], (count.get(nums[right]) || 0) + 1);
    while (count.size === total) {
      const value = nums[left];
      count.set(value, count.get(value) - 1);
      if (count.get(value) === 0) {
        count.delete(value);
      }
      left++;
    }
    answer += left;
  }
  return answer;
}

