function countCompleteSubarrays(nums) {
  const need = new Set(nums).size;
  let total = 0;
  for (let i = 0; i < nums.length; i++) {
    const seen = new Set();
    for (let j = i; j < nums.length; j++) {
      seen.add(nums[j]);
      if (seen.size === need) total++;
    }
  }
